import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const {
    Group, Mesh, IcosahedronGeometry, PlaneGeometry, InstancedMesh,
    Object3D, Color, DoubleSide, AdditiveBlending, DirectionalLight,
    AmbientLight, Vector3, Fog
  } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {};
  const BG = colors.background ?? '#0b0b10';
  const INK = colors.ink ?? '#16161d';
  const PAPER = colors.paper ?? '#e8ecf2';
  const ACCENT = colors.accent ?? '#ff2a38';

  const group = new Group();
  const timelines = [];
  const primHandles = [];
  const disposables = [];

  // ---- Backdrop stage (vertical gradient) ----
  const bgGeo = new PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial();
  {
    // vertical gradient via TSL
    // eslint-disable-next-line
    const { uv, mix, color } = require ? {} : {};
  }
  // Build TSL gradient with imports
  bgMat.side = DoubleSide;
  group.add(buildBackdrop());
  function buildBackdrop() {
    const geo = new PlaneGeometry(7, 6);
    const mat = new MeshBasicNodeMaterial();
    const bottom = new Color(BG);
    const top = new Color(INK);
    // simple TSL gradient
    // uv.y from 0 (bottom) to 1 (top)
    // handled below with imported nodes
    applyGradient(mat, bottom, top);
    const m = new Mesh(geo, mat);
    m.position.set(0, 0, -2.5);
    disposables.push(geo, mat);
    return m;
  }

  // ---- Lights ----
  const ambient = new AmbientLight(new Color(PAPER), 0.4);
  group.add(ambient);
  const key = new DirectionalLight(new Color(PAPER), 1.0);
  key.position.set(3, 4, 5);
  group.add(key);
  const rim = new DirectionalLight(new Color(ACCENT), 0.9);
  rim.position.set(-4, 2, -3);
  group.add(rim);

  // ---- Particle field ----
  const FIELD = 1110;
  const CORE = 90;
  const geoParticle = new IcosahedronGeometry(0.012, 0);
  disposables.push(geoParticle);

  const fieldMat = new MeshStandardNodeMaterial();
  fieldMat.color = new Color(PAPER);
  fieldMat.roughness = 1.0;
  fieldMat.metalness = 0.0;
  fieldMat.emissive = new Color(PAPER);
  fieldMat.emissiveIntensity = 0.9;
  fieldMat.transparent = true;
  disposables.push(fieldMat);

  const coreMat = new MeshStandardNodeMaterial();
  coreMat.color = new Color(ACCENT);
  coreMat.roughness = 0.6;
  coreMat.metalness = 0.0;
  coreMat.emissive = new Color(ACCENT);
  coreMat.emissiveIntensity = 1.8;
  coreMat.transparent = true;
  coreMat.blending = AdditiveBlending;
  disposables.push(coreMat);

  const fieldMesh = new InstancedMesh(geoParticle, fieldMat, FIELD);
  const coreMesh = new InstancedMesh(geoParticle, coreMat, CORE);
  disposables.push(fieldMesh, coreMesh);

  const dummy = new Object3D();
  const anchors = []; // {x,y,z, phase, freq, amp}
  const center = new Vector3(0, 0, -1.5);

  // field: ellipsoidal shell 6 x 4 x 5, centered [0,0,-1.5]
  for (let i = 0; i < FIELD; i++) {
    let x, y, z;
    // random point in ellipsoid
    do {
      x = (Math.random() * 2 - 1);
      y = (Math.random() * 2 - 1);
      z = (Math.random() * 2 - 1);
    } while (x * x + y * y + z * z > 1);
    const px = center.x + x * 3.0;
    const py = center.y + y * 2.0;
    const pz = center.z + z * 2.5;
    anchors.push({
      pos: new Vector3(px, py, pz),
      phase: Math.random() * Math.PI * 2,
      freq: 0.05,
      amp: 0.04,
      dir: new Vector3(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5).normalize(),
      core: false
    });
  }

  // core: 90 within 0.5 radius sphere at origin
  const coreAnchors = [];
  for (let i = 0; i < CORE; i++) {
    let x, y, z;
    do {
      x = Math.random() * 2 - 1;
      y = Math.random() * 2 - 1;
      z = Math.random() * 2 - 1;
    } while (x * x + y * y + z * z > 1);
    const px = x * 0.5;
    const py = y * 0.5;
    const pz = z * 0.5;
    coreAnchors.push({
      pos: new Vector3(px, py, pz),
      phase: Math.random() * Math.PI * 2,
      freq: 0.05,
      amp: 0.03,
      dir: new Vector3(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5).normalize(),
      core: true
    });
  }

  // per-instance depth-based opacity via instanceColor scaling of emissive won't work directly;
  // we approximate falloff by scaling instance size + we rely on fog. Set base transform.
  function writeInstances(scaleFactor) {
    for (let i = 0; i < FIELD; i++) {
      const a = anchors[i];
      dummy.position.copy(a.pos);
      const s = scaleFactor;
      dummy.scale.setScalar(s);
      dummy.updateMatrix();
      fieldMesh.setMatrixAt(i, dummy.matrix);
    }
    fieldMesh.instanceMatrix.needsUpdate = true;
    for (let i = 0; i < CORE; i++) {
      const a = coreAnchors[i];
      dummy.position.copy(a.pos);
      dummy.scale.setScalar(scaleFactor);
      dummy.updateMatrix();
      coreMesh.setMatrixAt(i, dummy.matrix);
    }
    coreMesh.instanceMatrix.needsUpdate = true;
  }
  writeInstances(1);

  group.add(fieldMesh);
  group.add(coreMesh);

  // ---- Fog on scene? attach to group userData; adapter may apply. Provide local fog color ----
  group.userData.fog = new Fog(new Color(BG), 4, 10);

  // ---- Text ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new Group();
  textGroup.position.z = 0.5;
  group.add(textGroup);

  const textMeshes = [];
  for (const item of items) {
    const role = item.role;
    let opts, y;
    if (role === 'hero') {
      opts = { fontSize: 124, color: PAPER, align: 'center', letterSpacingPx: -1 };
      y = 0.5;
    } else if (role === 'subhead') {
      opts = { fontSize: 40, color: PAPER, align: 'center', letterSpacingPx: 1 };
      y = 0.5 - 0.75;
    } else {
      opts = { fontSize: 18, color: ACCENT, align: 'center', letterSpacingPx: 3 };
      y = -2.25;
    }
    const t = ctx.fontAtlas.createText(String(item.text ?? ''), opts);
    t.position.set(0, y, 0);
    textGroup.add(t);
    textMeshes.push(t);
  }

  // ---- Primitives ----
  for (const prim of (config.cinematicPrimitives ?? [])) {
    const fn = ctx.primitives?.[prim.name];
    if (fn) {
      try {
        const h = fn(group, prim.params ?? {});
        if (h) primHandles.push(h);
      } catch (e) { /* ignore */ }
    }
  }

  // ---- Motion: particle emerge (from core outward) + entrance text ----
  const emergeProxy = { t: 0 };
  const emergeTl = gsap.timeline();
  emergeTl.fromTo(emergeProxy, { t: 0 }, {
    t: 1,
    duration: 1.4,
    ease: 'power3.out',
    onUpdate: () => {
      const p = emergeProxy.t;
      for (let i = 0; i < FIELD; i++) {
        const a = anchors[i];
        dummy.position.lerpVectors(center, a.pos, p);
        dummy.scale.setScalar(p);
        dummy.updateMatrix();
        fieldMesh.setMatrixAt(i, dummy.matrix);
      }
      fieldMesh.instanceMatrix.needsUpdate = true;
      for (let i = 0; i < CORE; i++) {
        const a = coreAnchors[i];
        dummy.position.lerpVectors(new Vector3(0, 0, 0), a.pos, p);
        dummy.scale.setScalar(p);
        dummy.updateMatrix();
        coreMesh.setMatrixAt(i, dummy.matrix);
      }
      coreMesh.instanceMatrix.needsUpdate = true;
    }
  });
  timelines.push(emergeTl);

  for (const t of textMeshes) {
    const tl = gsap.timeline({ delay: 0.6 });
    tl.fromTo(t.position, { y: t.position.y + 0.4 }, { y: t.position.y, duration: 0.7, ease: 'power3.out' });
    tl.fromTo(t.scale, { x: 1.04, y: 1.04, z: 1.04 }, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);
    timelines.push(tl);
  }

  // ---- Idle drift + core pulse ----
  let rafActive = true;
  const clock = { start: performance.now() };
  function tick() {
    if (!rafActive) return;
    const elapsed = (performance.now() - clock.start) / 1000;
    // only drift after emerge mostly done
    if (emergeProxy.t >= 0.999) {
      for (let i = 0; i < FIELD; i++) {
        const a = anchors[i];
        const off = Math.sin(elapsed * a.freq * Math.PI * 2 + a.phase) * a.amp;
        dummy.position.copy(a.pos).addScaledVector(a.dir, off);
        dummy.scale.setScalar(1);
        dummy.updateMatrix();
        fieldMesh.setMatrixAt(i, dummy.matrix);
      }
      fieldMesh.instanceMatrix.needsUpdate = true;
      for (let i = 0; i < CORE; i++) {
        const a = coreAnchors[i];
        const off = Math.sin(elapsed * a.freq * Math.PI * 2 + a.phase) * a.amp;
        dummy.position.copy(a.pos).addScaledVector(a.dir, off);
        dummy.scale.setScalar(1);
        dummy.updateMatrix();
        coreMesh.setMatrixAt(i, dummy.matrix);
      }
      coreMesh.instanceMatrix.needsUpdate = true;
    }
    // core pulse 1.5..1.8 at 0.1 Hz
    const pulse = 1.65 + Math.sin(elapsed * 0.1 * Math.PI * 2) * 0.15;
    coreMat.emissiveIntensity = pulse;
    requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    rafActive = false;
    for (const tl of timelines) { try { tl.kill(); } catch (e) {} }
    for (const h of primHandles) { try { h.cleanup?.(); } catch (e) {} }
    for (const d of disposables) { try { d.dispose?.(); } catch (e) {} }
    for (const t of textMeshes) {
      t.traverse?.((o) => {
        if (o.geometry) o.geometry.dispose?.();
        if (o.material) {
          if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose?.());
          else o.material.dispose?.();
        }
      });
    }
  };

  return group;

  // ---- TSL gradient helper ----
  function applyGradient(mat, bottomColor, topColor) {
    // Imported TSL nodes at top-level scope
    const g = tslGradient(bottomColor, topColor);
    mat.colorNode = g;
  }
}

// TSL imports separated
import { uv, mix, color } from 'three/tsl';
function tslGradient(bottomColor, topColor) {
  const grad = mix(color(bottomColor), color(topColor), uv().y);
  return grad;
}
